define("block_smartbot/chat",[],function(){var init=function(){var widget=document.querySelector("[data-block-smartbot]");if(!widget||widget.dataset.initialised){return;}var chat=widget.querySelector(".block_smartbot-chat"),launcher=widget.querySelector('[data-action="open"]'),close=widget.querySelector('[data-action="close"]');if(!chat||!launcher||!close){return;}widget.dataset.initialised="true";launcher.addEventListener("click",function(){chat.hidden=false;launcher.setAttribute("aria-expanded","true");close.focus();});close.addEventListener("click",function(){chat.hidden=true;launcher.setAttribute("aria-expanded","false");launcher.focus();});};return{init:init};});
